import {Component, HostListener, OnInit, ViewEncapsulation} from '@angular/core';
import {Router} from "@angular/router";
import {LanguageService} from "../../services/language/language.service";


@Component({
    selector: 'app-terminal',
    templateUrl: './terminal.component.html',
    styleUrls: ['./terminal.component.scss'],
    encapsulation: ViewEncapsulation.None
})
export class TerminalComponent implements OnInit {
    lines: string[] = [];
    waitForInput = false;

    constructor(private router: Router, private languageService: LanguageService) {
    }

    async ngOnInit() {
        if (this.terminal) {
            this.createLine(`last login: ${new Date().toLocaleString()}`);
            this.createLine('# in /users/arun-varghese');
            this.createCode('here are some commands you can run:', 'help | clear | exit');
            this.createNewLine();
            this.waitForInput = true;
        }
    }

    @HostListener('window:click', ['$event.target'])
    click(element: HTMLElement) {
        if (element.classList.contains('t-link')) {
            this.input.value = `open ${element.innerText}`;
            this.inputActive();
        }
    }

    @HostListener('window:keyup', ['$event'])
    submitInput(event: KeyboardEvent) {
        if (this.terminal && event.key == 'Enter') {
            const value = this.input?.value;
            this.waitForInput = false;
            this.clearInput();
            this.checkInputValue(value?.toLowerCase()?.trim() || '');
            this.inputActive();
        }
    }

    clearInput() {
        if (this.input?.value) {
            this.input.value = '';
        }
    }

    inputActive() {
        if (this.input && this.anchor) {
            this.waitForInput = true;
            this.input.focus();
            setTimeout(() => {
                this.anchor?.scrollIntoView();
            }, 100);

        }
    }

    get terminal() {
        return document.getElementById('terminal');
    }

    get input() {
        return document.getElementById('terminal-input') as HTMLInputElement;
    }

    get anchor() {
        return document.getElementById('anchor');
    }

    createNewLine() {
        this.lines.push('<br>');
    }

    createLine(text: string) {
        this.lines.push(text);
    }

    createSuccessLine(text: string) {
        this.lines.push(`<span class='t-green'>$ ${text} </span>`);
        this.createNewLine();
    }

    createErrorLine(text: string) {
        this.lines.push(`<span class='t-red'>$ ${text} </span>`);
    }

    createHelpLine(command, desc) {
        this.lines.push(`<div class='t-blue t-tab-1 t-help-command'>${command}</div><span> ${desc} </span>`);
    }

    createCode(code, text) {
        this.lines.push(`<span class="t-blue">${code}</span><br/><span class='t-text'> ${text} </span>`);
    }

    createContactLine(link, icon, label) {
        this.lines.push(`<a href='${link}' target='_blank' class="t-tab-1"><i class='${icon} white'></i>&nbsp;${label}</a>`);
    }

    createTabbedLine(text) {
        this.lines.push(`<span class='t-tab-1'>${text}</span>`);
    }

    createNavigationLine(link) {
        this.lines.push(`<a class='t-link t-tab-1'>${link}</a>`);
    }

    navigate(item) {
        this.router.navigate([item]);
    }

    checkInputValue(value: string) {
        if (value === 'help') {
            this.createSuccessLine(value);
            this.createLine('usage:');
            this.createHelpLine('about', 'who am i');
            this.createHelpLine('contact', 'contact me');
            this.createHelpLine('open', 'open &lt;page&gt;');
            this.createHelpLine('clear', 'clear terminal');
            this.createHelpLine('exit', 'close terminal');
            this.createNewLine();
        } else if (value === 'about') {
            this.createSuccessLine(value);
            this.createLine('hi, my name is <span class="t-blue">arun</span>')
            this.createLine('i have over 10 years of full-stack experience in the complete development life cycle of distributed web applications, from design to delivery.');
            this.createLine('in my free time, I work on front-end web development with popular frameworks to learn more about ui/ux and software architecture');
            this.createNewLine();
        } else if (value === 'open') {
            this.createSuccessLine(value);
            this.createLine('choose page:');
            this.createNavigationLine('highlights');
            this.createNavigationLine('experience');
            this.createNavigationLine('projects');
            this.createNavigationLine('resume');
            this.createNewLine();
        } else if (value === 'open highlights') {
            this.navigate('highlights');
        } else if (value === 'open experience') {
            this.navigate('experience');
        } else if (value === 'open projects') {
            this.navigate('projects');
        } else if (value === 'open resume') {
            this.createSuccessLine(value);
            this.languageService.translateService.get("Resume").subscribe(val => {
                window.open(val, "_blank");
            });
        } else if (value === 'contact') {
            this.createSuccessLine(value);
            this.createContactLine('mailto:arunv4700@gmail.com', 'fas fa-envelope', 'email');
            this.createContactLine('https://www.linkedin.com/in/varghesearun', 'fab fa-linkedin', 'linkedin');
            this.createContactLine('https://github.com/vararun', 'fab fa-github', 'github');
            this.createContactLine('https://codepen.io/avarghese', 'fab fa-codepen', 'codepen');
            this.createContactLine('https://www.instagram.com/chasing_arun', 'fab fa-instagram white', 'instagram');
            this.createNewLine();
        } else if (value === 'exit') {
            this.createErrorLine(value);
            this.navigate('home');
        } else if (value === 'clear') {
            this.createSuccessLine(value);
            this.waitForInput = false;
            this.lines = [];
            this.waitForInput = true;
        } else if (value === '') {
            this.createLine('$');
            return;
        } else {
            this.createErrorLine(value);
            this.createLine(`command not found: ${value}`)
            this.createNewLine();
        }
    }
}
